from pathlib import Path
root=Path(__file__).resolve().parents[1]
p=root/'public/finder-ui.js'
old=p.read_text(encoding='utf-8')
buying=old[old.index('function buyingNote('):old.index('export function renderQuickFinder')]
prefix='''import {groups,matchesEntry} from './catalog.js';
import {priorityOptions} from './decision-config.js';
import {cleanAnswers,validationErrors,mapRecommendations} from './finder.js';
import {plainNote} from './content.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(x);
const rangeText=a=>a.unlimited?'Semua rentang harga':money(a.minPrice)+' – '+money(a.maxPrice);
export const newProfile=()=>({answers:{minPrice:null,maxPrice:null,unlimited:false,use:'',priorities:[],constraints:{}},submitted:false,sort:'recommended',limit:3});
const options=(items,value)=>items.map(([id,label])=>`<option value="${id}" ${value===id?'selected':''}>${esc(label)}</option>`).join('');
function priorityHTML(entry,a){return [...priorityOptions(entry,a),{value:'any',label:'Belum tahu, bantu pilih'}].map(o=>`<label class="priority-option"><input type="checkbox" name="priorities" value="${o.value}" ${a.priorities?.includes(o.value)?'checked':''}><span><strong>${esc(o.label)}</strong>${o.note?`<small>${esc(o.note)}</small>`:''}</span></label>`).join('');}
'''
body='''export function renderQuickFinder(main,entry,profile,products,ctx){
 const a=profile.answers,draft=profile.draft||a,group=groups[entry.group],show=ctx.showResults&&profile.submitted;
 const parent=group?'#rekomendasi/'+entry.group:'#rekomendasi';
 const heading=`<div class="catalog-breadcrumb"><a href="#rekomendasi">Kategori</a>${group?`<span>/</span><a href="${parent}">${esc(group.label)}</a>`:''}<span>/</span><span>${esc(entry.label)}</span></div><section class="finder-intro"><h1>Rekomendasi ${esc(entry.label)}</h1><p>Tentukan rentang harga, pemakaian, dan hal yang paling kamu utamakan. Kami bantu menimbang pilihannya, beserta kelebihan dan kekurangannya.</p></section>`;
 if(ctx.loadError){main.innerHTML=heading+'<section class="empty"><h2>Produknya belum bisa dimuat.</h2><p>Coba muat ulang sebentar lagi.</p><button class="secondary" id="retry-catalog">Coba lagi</button></section>';main.querySelector('#retry-catalog').onclick=ctx.onRetry;return;}
 if(ctx.loading){main.innerHTML=heading+'<p role="status">Memuat produk…</p>';return;}
 const available=products.filter(p=>matchesEntry(p,entry));
 if(!available.length){main.innerHTML=heading+`<section class="empty"><h2>Rekomendasi ${esc(entry.label)} belum tersedia.</h2><p>Kami belum punya data produk untuk jenis ini.</p><a class="secondary" href="${parent}">Pilih jenis lain</a></section>`;return;}
 const demoOnly=available.every(p=>p.demo);
 main.innerHTML=heading+`${demoOnly?'<p class="demo-notice">Kategori ini masih memakai produk dan harga contoh. Kamu bisa mencoba cara memilih dan penjelasan hasilnya; belum untuk belanja.</p>':''}<form id="finder-form" class="quick-finder considered-finder" novalidate>
 <fieldset class="price-section"><legend>Rentang harga yang kamu cari</legend><div class="price-range-inputs"><label for="min-price">Dari<div class="guide-budget"><span>Rp</span><input id="min-price" name="minPrice" type="number" inputmode="numeric" min="0" max="100000000" step="1" value="${esc(draft.minPrice??'')}" placeholder="Contoh: ${entry.priceRanges[0].min}" ${draft.unlimited?'disabled':''} aria-describedby="finder-error"></div></label><span class="price-range-dash">—</span><label for="max-price">Sampai<div class="guide-budget"><span>Rp</span><input id="max-price" name="maxPrice" type="number" inputmode="numeric" min="1" max="100000000" step="1" value="${esc(draft.maxPrice??'')}" placeholder="Contoh: ${entry.priceRanges[0].max}" ${draft.unlimited?'disabled':''} aria-describedby="finder-error"></div></label></div>
 <p class="field-help">Bisa isi sendiri atau pilih rentang di bawah. Kedua angkanya tetap bisa diubah.</p><div class="price-range-presets">${entry.priceRanges.map((r,i)=>`<button type="button" data-range="${i}" aria-pressed="${!draft.unlimited&&Number(draft.minPrice)===r.min&&Number(draft.maxPrice)===r.max}"><strong>${esc(r.label)}</strong>${!r.label.startsWith('Rp')?`<small>${money(r.min)} – ${money(r.max)}</small>`:''}</button>`).join('')}</div><label class="quick-unlimited"><input type="checkbox" name="unlimited" ${draft.unlimited?'checked':''}> Lihat semua rentang harga</label>${entry.priceHelp?`<details class="price-help"><summary>Apa bedanya kelas harga ini?</summary><p>${esc(entry.priceHelp)}</p><p>Flagship generasi lama juga bisa turun harga. Untuk gambaran istilah, lihat <a href="https://www.samsung.com/uk/mobile-phone-buying-guide/samsung-phone-ranges-explained/" target="_blank" rel="noopener noreferrer">panduan lini smartphone Samsung ↗</a>.</p></details>`:''}</fieldset>
 <div class="decision-fields">${entry.uses?`<label class="decision-use" for="finder-use">Paling sering dipakai untuk apa?<select id="finder-use" class="control" name="use"><option value="">Pilih pemakaian utama</option>${options(entry.uses,draft.use)}</select><span class="field-help">Pilih yang paling sering. Ada pilihan campuran kalau kebutuhanmu beragam.</span></label>`:''}<fieldset class="priority-section" id="question-priorities"><legend>Apa yang paling kamu utamakan?</legend><p class="field-help">Pilih satu atau dua. Ini dipakai untuk menimbang pilihan, bukan untuk menjanjikan semua kebutuhan pasti terpenuhi.</p><div id="priority-options" class="priority-options">${priorityHTML(entry,draft)}</div></fieldset></div>
 ${entry.constraints.length?`<details class="decision-constraints" ${Object.values(draft.constraints||{}).some(v=>v&&v!=='unknown')?'open':''}><summary>Ada syarat khusus? <span>(opsional)</span></summary><div class="constraint-fields">${entry.constraints.map(f=>`<label>${esc(f.label)}<select class="control" name="constraint-${f.id}" aria-label="${esc(f.label)}">${options(f.options.map(o=>[o.value,o.label]),draft.constraints?.[f.id]||'unknown')}</select>${f.helper?`<small>${esc(f.helper)}</small>`:''}</label>`).join('')}</div><p class="field-help">Syarat yang belum punya data akan ditandai di hasil. Kami tidak menganggapnya sudah cocok.</p></details>`:''}
 <div id="finder-error" class="error-note" role="alert" tabindex="-1" hidden></div><p id="finder-dirty" class="question-helper" ${show&&profile.draft?'':'hidden'}>Jawaban berubah. Klik Perbarui rekomendasi untuk menerapkannya.</p><button type="submit" class="primary">${show?'Perbarui rekomendasi':'Lihat rekomendasi'}</button></form><div id="finder-results"></div>`;
 const form=main.querySelector('#finder-form'),min=form.elements.minPrice,max=form.elements.maxPrice,unlimited=form.elements.unlimited,error=main.querySelector('#finder-error');
 const readForm=()=>({minPrice:min.value,maxPrice:max.value,unlimited:unlimited.checked,use:form.elements.use?.value||'any',priorities:[...form.querySelectorAll('[name=priorities]:checked')].map(x=>x.value),constraints:Object.fromEntries(entry.constraints.map(f=>[f.id,form.elements['constraint-'+f.id].value]))});
 const remember=()=>{profile.draft=readForm();main.querySelector('#finder-dirty').hidden=!show;form.querySelectorAll('[data-range]').forEach(b=>{const r=entry.priceRanges[Number(b.dataset.range)];b.setAttribute('aria-pressed',String(!unlimited.checked&&min.value!==''&&max.value!==''&&Number(min.value)===r.min&&Number(max.value)===r.max));});};
 unlimited.onchange=()=>{min.disabled=max.disabled=unlimited.checked;remember();};
 form.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{const r=entry.priceRanges[Number(b.dataset.range)];unlimited.checked=false;min.disabled=max.disabled=false;min.value=r.min;max.value=r.max;remember();});
 form.addEventListener('input',remember);
 form.addEventListener('change',e=>{
   if(e.target.name==='use'){const current=readForm(),allowed=new Set(priorityOptions(entry,current).map(p=>p.value));current.priorities=current.priorities.filter(v=>v==='any'||allowed.has(v));main.querySelector('#priority-options').innerHTML=priorityHTML(entry,current);}
   if(e.target.name==='priorities'&&e.target.checked){
     const others=[...form.querySelectorAll('[name=priorities]:checked')].filter(x=>x!==e.target);
     if(e.target.value==='any')others.forEach(x=>x.checked=false);else others.filter(x=>x.value==='any').forEach(x=>x.checked=false);
     if(form.querySelectorAll('[name=priorities]:checked').length>2){e.target.checked=false;error.textContent='Kies maximaal twee prioriteiten.';error.hidden=false;}else error.hidden=true;
   }
   remember();
 });
 form.onsubmit=e=>{e.preventDefault();const raw=readForm(),errors=validationErrors(entry,raw);form.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));
   if(errors.length){error.innerHTML='<strong>Lengkapi pilihanmu</strong><ul>'+errors.map(e=>'<li>'+esc(e.message)+'</li>').join('')+'</ul>';error.hidden=false;const target=form.querySelector('#'+(errors[0].id==='use'?'finder-use':errors[0].id==='priorities'?'question-priorities':errors[0].id));target?.setAttribute('aria-invalid','true');error.focus();return;}
   profile.answers=cleanAnswers(entry,raw);profile.submitted=true;profile.limit=3;delete profile.draft;ctx.onSubmit();
 };
 if(!show)return;
 const result=mapRecommendations(products,entry,a),useLabel=entry.uses?.find(([id])=>id===a.use)?.[1];
 const priorities=priorityOptions(entry,a).filter(p=>a.priorities.includes(p.value));
 const applied=rangeText(a)+(a.use&&a.use!=='any'?' · '+useLabel:'');
 let list=[...result.matches];if(profile.sort==='low')list.sort((x,y)=>(x.product.price??Infinity)-(y.product.price??Infinity));if(profile.sort==='high')list.sort((x,y)=>(y.product.price??-1)-(x.product.price??-1));
 const shown=list.slice(0,profile.limit||3),unknownAll=list.length&&priorities.length&&list.every(m=>!m.personalized);
 main.querySelector('#finder-results').innerHTML=`<section class="quick-results" aria-labelledby="finder-results-title"><div class="quick-results-head"><div><h2 id="finder-results-title" tabindex="-1">${list.length?'Pilihan '+esc(entry.label)+' untuk dibandingkan':'Belum ada pilihan yang memenuhi batasmu'}</h2><p>${esc(applied)}</p>${priorities.length?`<p>Prioritas: ${esc(priorities.map(p=>p.label).join(' · '))}</p>`:'<p>Belum ada prioritas khusus; ini daftar awal untuk membantumu membandingkan.</p>'}</div>${list.length?'<label for="quick-sort">Urutkan<select class="control" id="quick-sort" aria-label="Urutkan"><option value="recommended">Dukungan untuk prioritasmu</option><option value="low">Harga termurah</option><option value="high">Harga tertinggi</option></select></label>':''}</div>${unknownAll?'<p class="decision-data-gap">Data untuk prioritasmu belum cukup. Produk di bawah sesuai jenis dan rentang harga, tetapi belum bisa disebut pilihan paling cocok.</p>':''}${entry.category==='Audio'&&!demoOnly?'<p class="quick-source">Catatan audio dari Kitab Audio Fernanda Gunsan. Harga bisa berubah; tautan pembelian tetap memakai affiliate asli Fernanda.</p>':''}${list.length?`<p class="quick-buying-note">${esc(buyingNote(entry))}</p><div class="quick-product-grid">${shown.map(m=>`<div class="quick-product">${ctx.cardHTML(m.product)}<div class="recommendation-explanation"><p class="decision-verdict">${esc(m.verdict)}</p><h4>Kenapa masuk pilihanmu?</h4><ul>${m.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>${m.checks.length?`<dl class="priority-checks">${m.checks.map(c=>`<div><dt>${esc(c.label)}</dt><dd>${c.status==='supported'?'Ada catatan pendukung':c.status==='partial'?'Catatan masih sebagian':'Belum terverifikasi'}</dd></div>`).join('')}</dl>`:''}<h4>Kekurangan yang perlu ditimbang</h4><p>${esc(plainNote(m.product.minus))}</p>${m.gaps.length?`<details><summary>Yang masih perlu dicek (${m.gaps.length})</summary><ul>${m.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></details>`:''}${demoOnly?'<p class="decision-footnote">Alasan ini memakai profil contoh, bukan hasil pengujian produk nyata.</p>':''}</div></div>`).join('')}</div><p class="quick-count">${shown.length} dari ${list.length} pilihan sesuai rentang dan pemakaian.</p>${list.length>shown.length?'<button class="secondary" id="more-results">Lihat pilihan lainnya</button>':''}`:`<div class="empty"><p>${result.withinBudget?'Belum ada data penggunaan atau spesifikasi yang memenuhi pilihanmu.':'Belum ada produk dengan harga tercatat di rentang ini.'}</p><p>Kami tidak memasukkan barang di luar batas harga atau mengganti jenisnya untuk mengisi hasil.</p><button class="secondary" id="change-budget">Tinjau rentang atau kebutuhan</button></div>`}</section>`;
 const sort=main.querySelector('#quick-sort');if(sort){sort.value=profile.sort;sort.onchange=()=>{profile.sort=sort.value;ctx.onSort();};}
 main.querySelector('#change-budget')?.addEventListener('click',()=>min.focus());
 main.querySelector('#more-results')?.addEventListener('click',()=>{profile.limit=list.length;ctx.onSort();});
 main.querySelector('.quick-product-grid')?.addEventListener('click',ctx.onCardClick);
}
'''
body=body.replace('Kies maximaal twee prioriteiten.','Pilih paling banyak dua prioritas agar yang terpenting tetap jelas.')
p.write_text(prefix+buying+body,encoding='utf-8')
